import {
  IsString,
  IsNotEmpty,
  IsNumber,
  IsArray,
  IsOptional,
  IsBoolean,
  ValidateNested,
} from 'class-validator';
import { Type } from 'class-transformer';

class PhaseDto {
  @IsString()
  @IsNotEmpty()
  phaseNumber: string;

  @IsString()
  @IsNotEmpty()
  startDate: string;

  @IsString()
  @IsNotEmpty()
  endDate: string;

  @IsString()
  @IsNotEmpty()
  returnCity: string;
}

export class CreateBusinessPackageDto {
  @IsString()
  @IsNotEmpty()
  packageName: string;

  @IsString()
  @IsNotEmpty()
  eventName: string;

  @IsString()
  @IsNotEmpty()
  duration: string;

  @IsString()
  @IsNotEmpty()
  country: string;

  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => PhaseDto)
  phases: PhaseDto[];

  @IsString()
  @IsOptional() 
  hotelName?: string;

  @IsString()
  @IsOptional() 
  hotelRating?: string;

  @IsNumber()
  @IsNotEmpty()
  maxPrice: number;

  @IsNumber()
  @IsNotEmpty()
  minimumPax: number;

  @IsString()
  @IsNotEmpty()
  description: string;

  @IsString()
  @IsNotEmpty()
  image: string;

  @IsString()
  @IsOptional()
  photo?: string;

  @IsString()
  @IsNotEmpty()
  createdBy: string;

  @IsString()
  @IsOptional() 
  packageStatus?: string;

  @IsBoolean()
  @IsOptional()
  isWithVisaAndAirTicket?: boolean;

  @IsBoolean()
  @IsOptional()
  isB2B?: boolean;

  @IsNumber()
  @IsOptional()
  B2BPrice?: number;
}
